package org.astian.suite.maps.ui.map

import android.content.Context
import org.astian.suite.maps.core.data.tiles.MapStyle
import org.astian.suite.maps.offline.GlyphPackStore
import org.json.JSONObject

/**
 * The Astian Maps look: the website's style, bundled as `assets/styles/astian-{light,dark}.json`
 * (generated by `packages/map-style`, `pnpm sync:android`). The engine hangs on `asset://` sprites,
 * so the sprite is pointed at the copy in files/ ([GlyphPackStore.spriteUrl]); once the glyph pack
 * is on disk the glyphs come from there too, so the map also draws with no signal.
 */
object BundledLook {
    /** The style JSON of [look] for the light/dark state, with its sprite and glyphs resolved, or
     *  null when the asset cannot be read. */
    fun json(context: Context, look: MapStyle, dark: Boolean): String? {
        val raw = runCatching {
            context.assets.open(look.uriFor(dark).removePrefix("asset://")).bufferedReader().use { it.readText() }
        }.getOrNull() ?: return null
        return prepare(context, raw)
    }

    /** Points a bundled look's sprite (and, when installed, its glyphs) at files on disk. */
    fun prepare(context: Context, json: String): String = runCatching {
        val root = JSONObject(json)
        GlyphPackStore.spriteUrl(context, "astian")?.let { root.put("sprite", it) }
        GlyphPackStore.glyphUrl(context)?.let { root.put("glyphs", it) }
        root.toString()
    }.getOrDefault(json)
}
